-- 004: Pre-Built Report (4 Photos per Page)
--
-- Same title-page cover as 002/003 (framed top and bottom by a rule, sized
-- to roughly a page via the Spacer paragraph, no photo-upload slot) followed
-- by five numbered sections, each with a summary line and 4 photo slots
-- arranged as a 2x2 grid (two stacked 2-up rows at 48% width) rather than a
-- single 4-wide row -- matching CompanyCam's own "4 photos per page"
-- template, and keeping each photo a readable size instead of squeezing four
-- into one row. Photo numbering is continuous across sections (1-20).
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-004-prebuilt-report-4up',
  NULL,
  NULL,
  '004: Pre-Built Report (4 Photos per Page)',
